        check("exactQuotient(10, 5)", 2.0, ExactDivision.exactQuotient(10, 5));
        check("exactQuotient(-7, 2)", -3.5, ExactDivision.exactQuotient(-7, 2));
        check("exactQuotient(1, 2)", 0.5, ExactDivision.exactQuotient(1, 2));
        check("exactQuotient(3, 8)", 0.375, ExactDivision.exactQuotient(3, 8));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
